const T20Multiclass=(()=>{
 function path(c,r,until=T20Builder.level(c)){const n=Math.min(T20Builder.level(c),until);return Array.from({length:n},(_,i)=>i===0?c.classe:r.classes[c.trajetoria?.[i]]?c.trajetoria[i]:c.classe);}
 function tracks(c,r,until){const levels=new Map();return path(c,r,until).map((id,i)=>{const n=(levels.get(id)||0)+1;levels.set(id,n);return {id,n,global:i+1,classe:r.classes[id]};});}
 function classes(c,r,until){const map=new Map();for(const row of tracks(c,r,until))map.set(row.id,row);return [...map.values()];}
 function level(c,r,id=c.classe,until){if(!r)return T20Builder.level(c);return classes(c,r,until).filter(x=>r.classes[id]?x.id===id:x.classe?.nome===id).reduce((s,x)=>s+x.n,0);}
 function at(c,r,n){return tracks(c,r,n).at(-1);}
 function powerClass(p,r,c){return (c?classes(c,r).map(x=>x.classe).filter(Boolean):Object.values(r.classes)).find(cl=>cl.poderes.some(x=>x.id===p.id));}
 function abilityLevel(c,r,p){const cl=powerClass(p,r,c);return cl?level(c,r,cl.id):T20Builder.level(c);}
 function key(c,name){return name==='Arcanista'?(c.caminho==='Feiticeiro'?'car':'int'):name==='Bardo'?'car':['Clérigo','Druida'].includes(name)?'sab':null;}
 function health(c,r,a){const rows=classes(c,r),first=r.classes[c.classe],attr=a.con;return (first?.pv||0)+attr+rows.reduce((s,x)=>s+Math.max(0,x.n-(x.id===c.classe?1:0))*Math.max(1,(x.classe?.pv_por_nivel||0)+attr),0);}
 function mana(c,r,a){const rows=classes(c,r),keys=new Set(rows.map(x=> T20Supplements.magicAttribute(c,r,x.classe)||key(c,x.classe?.nome)||(x.classe?.nome==='Paladino'?'car':null)).filter(Boolean));return rows.reduce((s,x)=>s+(x.classe?.pm||0)*x.n,0)+[...keys].reduce((s,k)=>s+a[k],0);}
 function label(c,r){return classes(c,r).filter(x=>x.classe).map(x=>x.classe?.nome+' '+x.n).join(' / ');}
 function active(c,r){return classes(c,r).length>1;}
 function project(c,r,id){const rows=tracks(c,r).filter(x=>x.id===id),map=new Map(rows.map(x=>[x.global,x.n])),local=rows.length,entries=(c.magiasClasse||[]).filter(x=>x.startsWith(id+'|')).map(x=>x.slice(id.length+1));return {...c,poderesGlobais:(c.evolucao||[]).map(x=>x.slice(x.indexOf(':')+1)).filter(id=>r.poderes[id]&&r.poderes[id].tipo!=='Classe'),classe:id,nivel:local,trajetoria:[],magias:(c.magiasClasse||[]).length||id!==c.classe?entries:c.magias,escolas:(c.escolasClasse||[]).filter(x=>x.startsWith(id+'|')).map(x=>x.slice(id.length+1)).length?(c.escolasClasse||[]).filter(x=>x.startsWith(id+'|')).map(x=>x.slice(id.length+1)):id===c.classe?c.escolas:[],evolucao:(c.evolucao||[]).filter(x=>map.has(Number(x.split(':')[0]))).map(x=>map.get(Number(x.split(':')[0]))+':'+x.slice(x.indexOf(':')+1)),magiasCopiadas:r.classes[id]?.nome==='Arcanista'?c.magiasCopiadas:[]};}
 function spellSlots(c,r){return classes(c,r).flatMap(x=>T20Builder.spellSlots(project(c,r,x.id),r).map(s=>({...s,classId:x.id})));}
 function spellAllocation(c,r){return classes(c,r).every(x=>T20Builder.spellAllocation(project(c,r,x.id),r));}
 function spellSources(c,r){return classes(c,r).flatMap(x=>project(c,r,x.id).magias.map(id=>r.magias[id]).filter(Boolean).map(m=>({...m,tipo:x.classe?.livro_id==='ghanor-base-2022'||['Universal','Ghanor'].includes(m.tipo)?(x.classe?.magia?.tipo==='Divina'?'Divina':'Arcana'):m.tipo,fonte:'Classe · '+x.classe?.nome,classOrigin:x.id,atributo:T20Supplements.magicAttribute(c,r,x.classe)||key(c,x.classe?.nome)})));}
 function spellCount(c,r){return classes(c,r).reduce((s,x)=>s+project(c,r,x.id).magias.length,0);}
 function syncSpells(c,r){const ids=new Set(classes(c,r).map(x=>x.id));c.magiasClasse=(c.magiasClasse||[]).filter(x=>ids.has(x.slice(0,x.indexOf('|'))));c.magias=[...new Set((c.magiasClasse||[]).map(x=>x.slice(x.indexOf('|')+1)))];}
 function arcanistSpells(c,r){const arc=Object.values(r.classes).find(x=>x.nome==='Arcanista');return active(c,r)?project(c,r,arc.id).magias:c.magias;}
 return {path,tracks,classes,level,at,powerClass,abilityLevel,key,health,mana,label,active,project,spellSlots,spellAllocation,spellSources,spellCount,syncSpells,arcanistSpells};
})();

function builderMulticlassUI(){const c=builderCharacter,r=T20CreatorRules,n=T20Builder.level(c);if(!r.classes[c.classe]||n<2)return '';return '<details class="builder-feature-panel builder-multiclass-config" '+(T20Multiclass.active(c,r)?'open':'')+'><summary>Multiclasse: escolher outra classe em um nível<small>Opcional · deixe como está para continuar na mesma classe</small></summary><div class="builder-feature-content"><h3>Classe em cada nível</h3><p>'+esc(T20Multiclass.label(c,r))+'</p><p>Ao entrar em outra classe, recebe suas habilidades e PV de evolução. Perícias e proficiências iniciais vêm da primeira classe.</p><div class="builder-grid">'+T20Multiclass.tracks(c,r).slice(1).map(x=>'<label>'+x.global+'º nível do personagem<select data-mc-level="'+x.global+'">'+Object.values(T20Supplements.collection(r.classes,c)).map(cl=>'<option value="'+cl.id+'" '+(cl.id===x.id?'selected':'')+'>'+esc(cl.nome+' · '+cl.sigla)+'</option>').join('')+'</select><small>'+esc(x.classe?.nome)+' · '+x.n+'º nível da classe</small></label>').join('')+'</div>'+T20Multiclass.classes(c,r).filter(x=>x.id!==c.classe).map(x=>'<details class="builder-feature-panel"><summary>'+esc(x.classe?.nome)+' '+x.n+'<small>Habilidades e regras da classe</small></summary><div class="builder-feature-content">'+builderClassReference(x.classe)+builderInitialFeatures(x.classe)+'</div></details>').join('')+(T20Builder.hasClass(c,r,'Arcanista')&&r.classes[c.classe]?.nome!=='Arcanista'?builderSelect('Caminho do arcanista','caminho',['Mago','Bruxo','Feiticeiro'].map(x=>'<option '+(c.caminho===x?'selected':'')+'>'+x+'</option>').join(''))+builderArcanistChoices():'')+'</div></details>';}
function builderMulticlassSpellsUI(){const c=builderCharacter,r=T20CreatorRules;return T20Multiclass.classes(c,r).filter(x=>T20Multiclass.key(c,x.classe?.nome)).map(x=>{const local=T20Multiclass.project(c,r,x.id),slots=T20Builder.spellSlots(local,r),selected=local.magias;return '<section class="builder-feature-panel"><h3>Magias de '+esc(x.classe?.nome)+' · '+x.n+'º nível</h3><p>'+selected.length+' de '+slots.length+' magias aprendidas por esta classe.</p>'+(['Bardo','Druida'].includes(x.classe?.nome)?'<div class="builder-grid">'+[...new Set(Object.values(r.magias).map(m=>m.escola))].map(s=>'<label><input type="checkbox" data-mc-school="'+x.id+'" value="'+esc(s)+'" '+(local.escolas.includes(s)?'checked':'')+'> '+esc(s)+'</label>').join('')+'</div>':'')+'<div class="builder-grid">'+Object.values(r.magias).filter(m=>slots.some(s=>T20Builder.spellCompatible(local,r,m,s))).map(m=>'<details class="builder-feature-panel"><summary><label><input type="checkbox" data-mc-spell="'+x.id+'" value="'+m.id+'" '+(selected.includes(m.id)?'checked':'')+(selected.length>=slots.length&&!selected.includes(m.id)?' disabled':'')+'> '+esc(m.nome)+' · '+m.circulo+'º</label></summary><div class="builder-feature-content"><p>'+esc(m.texto)+'</p></div></details>').join('')+'</div></section>';}).join('');}
function bindBuilderMulticlass(){const c=builderCharacter,r=T20CreatorRules;for(const el of document.querySelectorAll('[data-mc-level]'))el.onchange=()=>{const n=Number(el.dataset.mcLevel);c.trajetoria=T20Multiclass.path(c,r);c.trajetoria[n-1]=el.value;c.evolucao=c.evolucao.filter(x=>Number(x.split(':')[0])<n);c.aumentos=c.aumentos.filter(x=>Number(x.split(':')[0])<n);c.treinosNivel=c.treinosNivel.filter(x=>Number(x.split(':')[0])<n);c.escolhasHabilidades=c.escolhasHabilidades.filter(x=>Number(x.split(':')[0])<n);if(!(c.magiasClasse||[]).length)c.magiasClasse=c.magias.map(id=>c.classe+'|'+id);T20Multiclass.syncSpells(c,r);const pos=scrollY;renderBuilder();window.scrollTo(0,pos);scheduleBuilderSave();};for(const el of document.querySelectorAll('[data-mc-spell],[data-mc-school]'))el.onchange=()=>{const school=!!el.dataset.mcSchool,id=el.dataset.mcSchool||el.dataset.mcSpell,key=school?'escolasClasse':'magiasClasse',value=id+'|'+el.value;if(!c[key].length&&id===c.classe)c[key]=(school?c.escolas:c.magias).map(x=>id+'|'+x);if(school&&el.checked&&c[key].filter(x=>x.startsWith(id+'|')).length>=3){el.checked=false;return;}c[key]=c[key].filter(x=>x!==value);if(el.checked)c[key].push(value);if(!school)T20Multiclass.syncSpells(c,r);const pos=scrollY;renderBuilder();window.scrollTo(0,pos);scheduleBuilderSave();};}

function builderCalculationExplanation(c,r,v){const classes=T20Multiclass.classes(c,r),first=r.classes[c.classe],attr=v.selected.some(p=>p.nome==='Dom da Esperança')?v.a.sab:v.a.con;return '<details><summary>Como os valores foram calculados</summary><p>PV de classe: '+(first?.pv||0)+' iniciais + '+attr+' atributo'+classes.map(x=>{const n=x.n-(x.id===c.classe?1:0);return n?' + '+n+' × '+Math.max(1,(x.classe?.pv_por_nivel||0)+attr)+' ('+esc(x.classe?.nome)+')':'';}).join('')+'. Base com raça e linhagem: '+v.pvBase+'. PV finais com poderes, itens e ajustes: '+v.pv+'.</p><p>PM de classe: '+classes.map(x=>x.n+' × '+(x.classe?.pm||0)+' ('+esc(x.classe?.nome||'classe pendente')+')').join(' + ')+'. Atributos são somados uma vez por atributo. Base com raça: '+v.pmBase+'. PM finais com poderes, itens, sacrifícios e ajustes: '+v.pm+'.</p><p>Defesa: 10 + '+v.defAttribute+' atributo + '+(v.gear.armor+c.armadura)+' armadura + '+(v.gear.shield+c.escudo)+' escudo + '+v.defRace+' raça + '+v.defClass+' classe + '+v.defPower+' poderes. Total com os demais efeitos: '+v.defense+'.</p></details>';}

